/**
 * jev-skill-suggestion — Claude Mod
 *
 * Takes the skill listing out of the context window and has TypeSafe's Jev,
 * a System One decision model, suggest at most one skill per prompt, going
 * by the skills' descriptions. The skills stay installed and loadable; what
 * goes away is the listing the engine sends the model every session, one
 * line per skill, whether the prompt has anything to do with any of them.
 *
 * The decision follows TypeSafe's "Skill suggestion" cookbook: two requests
 * per prompt, one to rank every skill and ask whether the prompt needs a
 * skill at all, one to re-read the top few with their full text and let each
 * be rejected on its own. Either may come back empty-handed.
 *
 * The hooks:
 *   prompt.attachment  — the engine's `skill_listing` attachment is answered
 *                        with `{ text: null }` (left out) or trimmed to the
 *                        names in `alwaysListed`. Its names are remembered:
 *                        they are the engine's word on which skills the model
 *                        may invoke.
 *   prompt.submit      — the two requests run, and the winner (if any) is
 *                        attached to the prompt as a `<skill_relevance>`
 *                        block: with the skill's own SKILL.md inside it
 *                        (`inject: "content"`, the default), so the skill
 *                        loads even when `skillOverrides` hides it from the
 *                        model, or with its name for the Skill tool
 *                        (`inject: "suggest"`).
 *   session.start, tool.describe, tool.call
 *                      — the `find_skill` tool: registered when the session
 *                        starts, kept out of ToolSearch so the model sees its
 *                        description, and answered by the same two requests
 *                        on the sub-task the model names. The prompt.submit
 *                        pick covers the prompt; this covers what turns up
 *                        mid-turn, for a model that sees most skills by name
 *                        only. It answers a name for the Skill tool, never a
 *                        SKILL.md.
 *   skill.prompt       — observation: whether the model took the suggestion,
 *                        or loaded a skill on its own. Also writes the prompt
 *                        of the plugin's own `/jev-skill-suggestion:setup`,
 *                        which hides every skill from the engine's listing
 *                        (user-invocable-only) once the person has seen the
 *                        list and said yes; the model makes the edit with its
 *                        own tools, so it shows and asks like any other.
 *
 * Jev is reached one of two ways, whichever key is configured: TypeSafe's
 * own API (`typesafeApiKey`), which reports a calibrated confidence, or the
 * Vercel AI Gateway (`gatewayApiKey`), which does not. With neither, the
 * engine's own `$.model.classify` stands in with a single request and no
 * gate, so the mod is useful without any account.
 *
 * The candidates come from `$.command.list()`, not from the listing: the
 * listing is only rendered at the turn's first request, after `prompt.submit`
 * has run, so the first prompt of a session would otherwise have nothing to
 * choose from. The listing, once seen, narrows the candidates to what the
 * engine itself would have shown.
 *
 * The second request reads the opening of each shortlisted skill's SKILL.md,
 * found on disk by how Claude Code lays skills out (project and user
 * `.claude/skills` and `.claude/commands`, a plugin's install path from
 * `~/.claude/plugins/installed_plugins.json`). A body that cannot be found
 * leaves that skill with its one-line description; nothing fails over it.
 *
 * Only the main conversation is handled. A subagent's own listing is left as
 * the engine renders it: its prompt is a tool call's argument, not a
 * `prompt.submit`, so nothing here could suggest for it. `find_skill`, where a
 * subagent is given it, is the exception (unverified: calls carry `agentId`).
 *
 * Every failure path is fail-open: a request that errors or runs past the
 * latency budget lets the prompt through with no suggestion, and the listing
 * hook always answers the same way, so the model's prompt cache holds.
 *
 * The API key comes from the plugin's options (userConfig "typesafeApiKey"
 * or "gatewayApiKey"). Never hardcode it in this file.
 *
 * Needs Claude Code >= 2.1.278: the
 * `prompt.attachment` event is that release's. Typed against Anthropic's
 * declarations: https://github.com/anthropics/claude-code/tree/main/mods
 *
 * Privacy: with a key set, the prompt text, every candidate skill's name and
 * description, and the opening of each shortlisted skill's SKILL.md are sent
 * to whichever backend the key belongs to.
 */
import type { EngineInterface, Register } from 'claude-code'
import {
  DEFAULT_BASE_URL,
  DEFAULT_MODEL,
  FIND_SKILL_TOOL,
  NONE,
  SETUP_COMMAND,
  builtinWide,
  catalog,
  classifyText,
  commandLike,
  configDirOf,
  contextFree,
  decide,
  describeRerank,
  describeSetup,
  describeStatus,
  describeStillListed,
  describeWide,
  detailOf,
  displayIds,
  canonical,
  endpoint,
  findSkillResult,
  injectionBlock,
  installPathsOf,
  parseListing,
  parseNames,
  passesGate,
  pluginFileCandidates,
  readRerank,
  readSkillSettings,
  modelInvocable,
  readWide,
  recentContextOf,
  modelOf,
  recordLine,
  rerankQuestions,
  requestBody,
  requestHeaders,
  selectProvider,
  setupAborted,
  setupInstructions,
  setupPlan,
  shortlistOf,
  validBackup,
  skillFileCandidates,
  suggestionBlock,
  syncedFileCandidates,
  trimListing,
  underConfigDir,
  wideQuestions,
} from './policy.ts'
import type { Candidate, PolicyConfig, Provider, RecentContext, Rerank, Skill, Trace, Wide } from './policy.ts'

/** Prompt origins that are not a task of the person's: nothing to suggest for. */
const NOT_A_TASK = new Set([
  'task-notification',
  'peer',
  'peer-send-message',
  'projects-relay',
  'observer',
  'observer-activity',
])

/** A SKILL.md as found on disk. */
type SkillFile = { path: string; markdown: string }

/** The backend the keys select, with where and as which model it is asked. */
type Backend = { active: Provider | null; apiKey: string; modelId: string; url: string }

/** What `choose` answers. */
interface Choice {
  pick: Skill | null
  /** Why, for the log line. */
  reason: string
  file: SkillFile | null
  /** False when a request failed or timed out: "no pick" is then not an answer. */
  answered: boolean
  /** What the requests answered, for the record file; null when none was asked. */
  trace: Trace | null
}

/** What `choose` reads from the options, and the session state it shares with the hooks. */
interface ChooseContext {
  readonly backendOf: (typesafeEnv: string | undefined, gatewayEnv: string | undefined) => Backend
  readonly forced: string
  readonly neverSuggested: ReadonlySet<string>
  readonly logDecisions: boolean
  readonly recordDecisions: boolean
  readonly sendRecentContext: boolean
  readonly timeoutMs: number
  readonly rerankTimeoutMs: number
  readonly rerankEnabled: boolean
  readonly excerptChars: number
  readonly policy: PolicyConfig
  // Session state, filled in as hooks run.
  files: Map<string, SkillFile | null>
  unusableReported: boolean
  displayToId: Map<string, string> | null
  /** Each session's record file as written so far, by session id. */
  records: Map<string, string>
}

/**
 * The turn before `current` (null mid-turn), sent beside the request; null
 * when off or unreadable, and for a subagent, whose conversation is not the
 * session's transcript.
 */
async function contextFor(
  $: EngineInterface,
  ctx: ChooseContext,
  current: string | null,
  agentId?: string,
): Promise<RecentContext | null> {
  if (!ctx.sendRecentContext || agentId) return null
  try {
    return recentContextOf(await $.session.messages(), current)
  } catch (error) {
    $.ui.log(`[jev-skill-suggestion] could not read the transcript: ${String(error)}`)
    return null
  }
}

/** A record file stops growing here, under `$.fs`'s 4 MiB per read and write. */
const RECORD_LIMIT = 3_500_000

/**
 * Appends one line to the session's record file,
 * `<config dir>/jev-skill-suggestion/decisions/<session id>.jsonl`. `$.fs`
 * writes whole files, so the content so far is kept in memory, read back from
 * disk the first time (a resumed session). Fails open, like everything else.
 */
async function record($: EngineInterface, ctx: ChooseContext, entry: Parameters<typeof recordLine>[1]) {
  if (!ctx.recordDecisions) return
  try {
    const configDir = await configDirFor($)
    if (!configDir) return
    const id = await $.session.id()
    const path = `${configDir}/jev-skill-suggestion/decisions/${id}.jsonl`
    let content = ctx.records.get(id)
    if (content === undefined) content = (await $.fs.exists(path)) ? await $.fs.read(path) : ''
    const next = content + recordLine(await $.clock.now(), entry)
    if (next.length > RECORD_LIMIT) return
    ctx.records.set(id, next)
    await $.fs.write(path, next)
  } catch (error) {
    $.ui.log(`[jev-skill-suggestion] could not record the decision: ${String(error)}`)
  }
}

/** The user's config dir, or '' when HOME is unset and it cannot be named. */
async function configDirFor($: EngineInterface): Promise<string> {
  const home = (await $.env.get('HOME')) ?? ''
  return home ? configDirOf(home, await $.env.get('CLAUDE_CONFIG_DIR')) : ''
}

/**
 * Every command `$.command.list()` reports, under the id the engine lists,
 * runs and overrides it by. Throws as `$.command.list()` does.
 */
async function listCommands($: EngineInterface, ctx: ChooseContext, configDir: string) {
  const commands = await $.command.list()
  if (!ctx.displayToId && commands.some((command) => !commandLike(command.name))) {
    const found: { dir: string; markdown: string }[] = []
    for (const dir of [`${await $.session.cwd()}/.claude/skills`, configDir && `${configDir}/skills`]) {
      if (!dir || !(await $.fs.exists(dir))) continue
      for (const entry of await $.fs.list(dir)) {
        const file = `${dir}/${entry.name}/SKILL.md`
        if (entry.kind === 'dir' && (await $.fs.exists(file))) found.push({ dir: entry.name, markdown: await $.fs.read(file) })
      }
    }
    ctx.displayToId = displayIds(found)
  }
  return canonical(commands, ctx.displayToId ?? new Map())
}

/**
 * Jev's pick for `text`, with the pick's SKILL.md when found, or null when
 * the skills could not be listed. `restrictTo`, when
 * non-empty, keeps the candidates to those names: the listing's, for a pick
 * the model will load with the Skill tool (empty until the listing is seen).
 * `askGate` off leaves the gate questions out, so the gate passes: a model
 * that calls find_skill has already decided it wants a skill.
 */
async function choose(
  $: EngineInterface,
  ctx: ChooseContext,
  text: string,
  { restrictTo, askGate, context }: { restrictTo: ReadonlySet<string>; askGate: boolean; context: RecentContext | null },
): Promise<Choice | null> {
  const configDir = await configDirFor($)
  const { active, apiKey, modelId, url } = ctx.backendOf(await $.env.get('TYPESAFE_API_KEY'), await $.env.get('AI_GATEWAY_API_KEY'))

  /** One request to the active backend, or null on timeout, error or a non-2xx. */
  const ask = async (
    prompt: string,
    questions: Record<string, unknown>,
    what: string,
    budgetMs: number,
  ): Promise<string | null> => {
    if (!active) return null
    try {
      const response = await Promise.race([
        $.http.fetch(url, {
          method: 'POST',
          headers: requestHeaders(active, apiKey, modelId),
          body: requestBody(active, prompt, questions, modelId, context),
        }),
        $.clock.sleep(budgetMs),
      ])
      if (response && response.ok) return response.text
      if (response) $.ui.log(`[jev-skill-suggestion] ${active} responded ${response.status} to the ${what}`)
      else $.ui.log(`[jev-skill-suggestion] ${what} passed ${budgetMs}ms; no suggestion`)
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] ${what} failed: ${String(error)}`)
    }
    return null
  }

  /** A skill's file, found on disk by Claude Code's layout, or null. */
  const fileOf = async (
    skill: Skill,
    plugin: string | undefined,
  ): Promise<SkillFile | null> => {
    const cached = ctx.files.get(skill.name)
    if (cached !== undefined) return cached
    let found: SkillFile | null = null
    try {
      const relative = skillFileCandidates(skill.name, plugin)
      // The engine reads the project's `.claude/` (the working directory
      // only, not its ancestors) and the user's config dir.
      const candidates = [...relative, ...(configDir ? relative.map((file) => underConfigDir(configDir, file)) : [])]
      if (plugin && configDir) {
        const installed = `${configDir}/plugins/installed_plugins.json`
        if (await $.fs.exists(installed)) {
          for (const path of installPathsOf(await $.fs.read(installed), plugin)) {
            candidates.push(...pluginFileCandidates(path, skill.name, plugin))
          }
        }
      }
      // A claude.ai-synced skill sits under an account directory only
      // `$.fs.list` can name.
      if (configDir) {
        const synced = `${configDir}/skills/synced`
        if (await $.fs.exists(synced)) {
          const accounts = (await $.fs.list(synced)).filter((entry) => entry.kind === 'dir').map((entry) => entry.name)
          candidates.push(...syncedFileCandidates(configDir, accounts, skill.name))
        }
      }
      for (const file of candidates) {
        if (await $.fs.exists(file)) {
          found = { path: file, markdown: await $.fs.read(file) }
          break
        }
      }
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] could not read /${skill.name}: ${String(error)}`)
    }
    ctx.files.set(skill.name, found)
    return found
  }

  if (!ctx.unusableReported && !active) {
    ctx.unusableReported = true
    $.ui.log(`[jev-skill-suggestion] provider "${ctx.forced}" has no key set; using the built-in classifier`)
  }

  let commands: Awaited<ReturnType<typeof $.command.list>>
  try {
    commands = await listCommands($, ctx, configDir)
  } catch (error) {
    $.ui.log(`[jev-skill-suggestion] could not list the skills: ${String(error)}`)
    return null
  }
  // Loading the skill itself, the mod is not bound to what the engine would
  // list, but a skill the person turned `off` stays off: the overrides are
  // read from the user settings on every prompt, so an edit counts at once.
  const off = new Set<string>()
  try {
    const settingsPath = `${configDir}/settings.json`
    if (configDir && (await $.fs.exists(settingsPath))) {
      const { skillOverrides } = readSkillSettings(await $.fs.read(settingsPath))
      for (const [name, state] of Object.entries(skillOverrides)) if (state === 'off') off.add(name)
    }
  } catch (error) {
    $.ui.log(`[jev-skill-suggestion] could not read the skill overrides: ${String(error)}`)
  }
  const skills = catalog(commands, restrictTo, new Set([...ctx.neverSuggested, ...off]))
  if (skills.length === 0) {
    return { pick: null, reason: 'no candidate skills', file: null, answered: true, trace: null }
  }
  const pluginOf = new Map(commands.map((command) => [command.name, command.plugin]))

  // Request 1: rank everything, and ask whether the prompt wants a skill at all.
  const startedAt = await $.clock.now()
  let wide: Wide | null = null
  let model: string | null = null
  if (active) {
    const answer = await ask(text, wideQuestions(active, skills, { askGate }), 'ranking', ctx.timeoutMs)
    if (answer) {
      wide = readWide(answer)
      model = modelOf(answer)
    }
  } else {
    // No backend: the engine's own small-model classifier answers the same
    // question, with the descriptions folded into the text it reads. One
    // label, no gate, no rerank.
    try {
      const label = await $.model.classify(classifyText(text, skills), [
        NONE,
        ...skills.map((skill) => skill.name),
      ])
      wide = builtinWide(label)
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] built-in classifier failed: ${String(error)}`)
    }
  }
  // What the decision model actually answered, whatever the policy then
  // does with it. This is the line that proves the ranking ran.
  if (ctx.logDecisions) {
    const ms = (await $.clock.now()) - startedAt
    $.ui.log(`[jev-skill-suggestion] jev: ${describeWide(wide, skills.length, ms)}`)
  }

  // Request 2: re-read the shortlist with each skill's full text, and let
  // every candidate be rejected on its own.
  let rerank: Rerank | null = null
  let rerankAttempted = false
  // Before the listing has been seen, `$.command.list()` may name a skill
  // the model is not allowed to invoke; its own frontmatter tells.
  const barred: string[] = []
  if (active && ctx.rerankEnabled && wide && passesGate(wide, ctx.policy)) {
    const candidates: Candidate[] = []
    for (const skill of shortlistOf(wide, skills, ctx.policy.shortlist)) {
      const body = (await fileOf(skill, pluginOf.get(skill.name)))?.markdown ?? null
      if (!modelInvocable(body)) {
        barred.push(skill.name)
        continue
      }
      candidates.push({ ...skill, detail: detailOf(skill, body, ctx.excerptChars) })
    }
    if (candidates.length > 0) {
      const rerankStartedAt = await $.clock.now()
      rerankAttempted = true
      const answer = await ask(text, rerankQuestions(active, candidates), 'rerank', ctx.rerankTimeoutMs)
      if (answer) rerank = readRerank(answer)
      if (ctx.logDecisions) {
        const ms = (await $.clock.now()) - rerankStartedAt
        const read = candidates.filter((candidate) => ctx.files.get(candidate.name)).length
        $.ui.log(
          `[jev-skill-suggestion] jev: ${describeRerank(rerank, ms)} · ${read}/${candidates.length} bodies read`,
        )
      }
    }
  }

  const offered = barred.length > 0 ? skills.filter((skill) => !barred.includes(skill.name)) : skills
  let decision = decide(wide, rerank, offered, ctx.policy, rerankAttempted)
  let pick = decision.name ? (skills.find((skill) => skill.name === decision.name) ?? null) : null
  // With the gate left out, the rerank's `fits` is the only check against a
  // wrong pick: a pick it never read (every shortlisted skill barred, so the
  // ranking's next one stands) is no answer.
  if (pick && !askGate && !rerank) {
    decision = { name: null, reason: 'no rerank read the pick' }
    pick = null
  }
  // The winner's own frontmatter has the last word, whichever path picked it.
  if (pick && !barred.includes(pick.name) && !modelInvocable((await fileOf(pick, pluginOf.get(pick.name)))?.markdown ?? null)) {
    barred.push(pick.name)
    decision = { name: null, reason: `/${pick.name} has disable-model-invocation` }
    pick = null
  }
  if (ctx.logDecisions && barred.length > 0) {
    $.ui.log(
      `[jev-skill-suggestion] not model-invocable, left out: ${barred.map((name) => `/${name}`).join(', ')}`,
    )
  }
  const file = pick ? await fileOf(pick, pluginOf.get(pick.name)) : null
  return {
    pick,
    reason: decision.reason,
    file,
    answered: wide !== null && (!rerankAttempted || rerank !== null),
    trace: { wide, rerank, ms: (await $.clock.now()) - startedAt, model },
  }
}

export const register: Register = (on, options) => {
  const text = (key: string, fallback: string) =>
    typeof options[key] === 'string' && options[key] ? (options[key] as string) : fallback
  const number = (key: string, fallback: number) =>
    typeof options[key] === 'number' ? (options[key] as number) : fallback
  const flag = (key: string, fallback: boolean) =>
    typeof options[key] === 'boolean' ? (options[key] as boolean) : fallback

  const forced = text('provider', 'auto')

  // TypeSafe's own API is preferred when both keys are set: it is the only
  // one that reports a calibrated confidence. `provider` forces one,
  // including "builtin" to use neither. A key option wins; with none, the
  // key's environment variable (TYPESAFE_API_KEY, AI_GATEWAY_API_KEY) is
  // read at the first hook, since only `$` can read the environment; the
  // first answer stands for the process.
  let backend: Backend | null = null
  const backendOf = (typesafeEnv: string | undefined, gatewayEnv: string | undefined): Backend => {
    if (backend) return backend
    const typesafeKey = text('typesafeApiKey', '') || (typesafeEnv ?? '').trim()
    const gatewayKey = text('gatewayApiKey', '') || (gatewayEnv ?? '').trim()
    const active = selectProvider(forced, typesafeKey, gatewayKey)
    // Each backend keeps its own URL and model, so an override written for one
    // can never be sent to the other when `auto` picks differently than expected.
    backend = {
      active,
      apiKey: active === 'typesafe' ? typesafeKey : active === 'gateway' ? gatewayKey : '',
      modelId: !active
        ? ''
        : active === 'typesafe'
          ? text('typesafeModel', DEFAULT_MODEL.typesafe)
          : text('gatewayModel', DEFAULT_MODEL.gateway),
      url: !active
        ? ''
        : active === 'typesafe'
          ? endpoint('typesafe', text('typesafeBaseUrl', DEFAULT_BASE_URL.typesafe))
          : endpoint('gateway', text('gatewayBaseUrl', DEFAULT_BASE_URL.gateway)),
    }
    return backend
  }

  // The listing stays by default: `name-only` overrides (what the setup
  // writes) already take the descriptions out, and a listed name is what lets
  // the model load a skill another skill names.
  const hideListing = flag('hideListing', false)
  // "content": the mod reads the chosen skill's SKILL.md and attaches it, so
  // the skill loads even when the engine lists it as user-invocable-only or
  // off. "suggest": the cookbook's block alone, and the model loads the skill
  // with the Skill tool, which honours the engine's skillOverrides.
  const injectContent = text('inject', 'content') !== 'suggest'
  const alwaysListed = parseNames(text('alwaysListed', ''))
  const neverSuggested = parseNames(text('neverSuggested', ''))
  const rerankEnabled = flag('rerank', true)
  const excerptChars = number('excerptChars', 700)
  const timeoutMs = number('timeoutMs', 800)
  // The second request carries each shortlisted SKILL.md's opening and one
  // question per candidate, so it gets its own, longer budget.
  const rerankTimeoutMs = number('rerankTimeoutMs', 2500)
  const logDecisions = flag('logDecisions', true)
  const recordDecisions = flag('recordDecisions', true)
  const sendRecentContext = flag('sendRecentContext', true)
  const findSkill = flag('findSkill', true)
  const policy: PolicyConfig = {
    shortlist: Math.max(1, Math.round(number('shortlist', 3))),
    gateThreshold: number('gateThreshold', 0.3),
    fitsThreshold: number('fitsThreshold', 0.5),
  }

  // The names every skill_listing attachment carried so far. Once non-empty,
  // only these are offered to the decision model: the listing is the engine's
  // word on which skills the model is allowed to invoke, and `$.command.list()`
  // also names commands the model may not.
  const listed = new Set<string>()
  // The skill suggested for the current prompt, so a skill.prompt that loads
  // it can be told apart from one the model reached for on its own.
  let suggested: string | null = null
  // Each skill's SKILL.md as first found, with where, or null when nowhere:
  // read once per session, since the second request wants it on every prompt
  // it is on, and the injection wants it whole.
  const files = new Map<string, SkillFile | null>()
  // The skills whose instructions were already attached this session: a
  // second time, the block only names the skill again.
  const injected = new Set<string>()
  // Said once, the first time a hook runs. A mod that loaded and one that
  // never loaded are otherwise told apart only by the absence of later lines,
  // and absence is not evidence: with the listing gone, silence is the norm.
  let announced = false
  // The setup hint, once per session.
  let hintedSetup = false

  const state: ChooseContext = {
    backendOf,
    forced,
    files,
    neverSuggested,
    logDecisions,
    recordDecisions,
    sendRecentContext,
    timeoutMs,
    rerankTimeoutMs,
    rerankEnabled,
    excerptChars,
    policy,
    // A backend named in the options but missing its key degrades to the
    // built-in classifier, which is silent; say so once, when a hook first runs.
    unusableReported: forced === 'auto' || forced === 'builtin',
    // A skill whose frontmatter `name:` has spaces ("PocketBase API Rules") is
    // reported by `$.command.list()` under that name, but the engine lists,
    // runs and overrides it by its directory name (`pb-api-rules`). The map
    // from one to the other is read from disk once per session, in whichever
    // hook first needs it.
    displayToId: null,
    records: new Map(),
  }

  on('prompt.attachment', { type: 'skill_listing' }, async ($, e, next) => {
    if (!announced) {
      announced = true
      const { active, url } = backendOf(await $.env.get('TYPESAFE_API_KEY'), await $.env.get('AI_GATEWAY_API_KEY'))
      if (logDecisions) {
        $.ui.log(`[jev-skill-suggestion] ${describeSetup(active, url, hideListing, forced === 'builtin')}`)
      }
    }

    const skills = parseListing(e.text)
    // A subagent's listing may name skills the main conversation's does not.
    if (!e.agentId) for (const skill of skills) listed.add(skill.name)

    // A listed skill that still brings its whole description is context the
    // setup command would trim to the name: say so once.
    // ponytail: a `prefix:name` is taken for a plugin's skill, which
    // skillOverrides cannot trim; read `$.command.list()` sources if a
    // colon-named user skill ever shows up.
    const described = skills.filter((skill) => skill.description && !skill.name.includes(':')).length
    if (!hintedSetup && described > 0 && !e.agentId) {
      hintedSetup = true
      if (logDecisions) $.ui.log(`[jev-skill-suggestion] ${describeStillListed(described)}`)
    }

    // A subagent's listing is not ours: nothing here suggests for a subagent,
    // so hiding its listing would leave it with no skills at all.
    if (!hideListing || e.agentId) return next(e)

    const kept = trimListing(e.text, alwaysListed)
    if (logDecisions) {
      const keptNames = kept
        ? parseListing(kept)
            .map((skill) => skill.name)
            .join(', ')
        : 'none'
      $.ui.log(
        `[jev-skill-suggestion] withheld the skill listing (${skills.length} skills, ${e.text.length} characters); kept listed: ${keptNames}`,
      )
    }
    // Answered without `next`: the engine's text never reaches the model.
    return { text: kept }
  })

  on('prompt.submit', async ($, e, next) => {
    if (!announced) {
      announced = true
      const { active, url } = backendOf(await $.env.get('TYPESAFE_API_KEY'), await $.env.get('AI_GATEWAY_API_KEY'))
      if (logDecisions) {
        $.ui.log(`[jev-skill-suggestion] ${describeSetup(active, url, hideListing, forced === 'builtin')}`)
      }
    }
    suggested = null

    // Notifications and peer messages are not tasks; a typed `/name` already
    // names its skill; "ok" or "繼續" carries no task the prompt alone shows.
    // None of them gets a suggestion.
    if (!e.text.trim() || /^\/\S/.test(e.text.trim())) return next(e)
    if (e.origin && NOT_A_TASK.has(e.origin.kind)) return next(e)
    if (contextFree(e.text)) {
      if (logDecisions) $.ui.log('[jev-skill-suggestion] no suggestion: a reply with no task of its own')
      return next(e)
    }

    // Content mode loads the skill itself, so it is not bound to what the
    // engine lists; "suggest" leaves loading to the Skill tool, which is.
    const context = await contextFor($, state, e.text)
    const choice = await choose($, state, e.text, { restrictTo: injectContent ? new Set() : listed, askGate: true, context })
    if (!choice) return next(e)
    const { pick, file } = choice
    await record($, state, { source: 'prompt', text: e.text, context, pick: pick?.name ?? null, reason: choice.reason, answered: choice.answered, trace: choice.trace })
    // A row in the transcript scrolls away; this line stays on screen.
    if (logDecisions) $.ui.status(describeStatus(pick?.name ?? null))
    if (logDecisions) {
      $.ui.log(
        pick
          ? `[jev-skill-suggestion] suggesting /${pick.name}: ${choice.reason}`
          : `[jev-skill-suggestion] no suggestion: ${choice.reason}`,
      )
    }

    suggested = pick?.name ?? null
    let block: string | null
    if (injectContent && pick) {
      const projectDir = await $.session.cwd()
      block = injectionBlock(pick, file?.markdown ?? null, file?.path ?? null, projectDir, injected.has(pick.name))
      if (logDecisions) {
        $.ui.log(
          file
            ? injected.has(pick.name)
              ? `[jev-skill-suggestion] /${pick.name} already injected this session; named again`
              : `[jev-skill-suggestion] injected /${pick.name} from ${file.path} (${file.markdown.length} characters)`
            : `[jev-skill-suggestion] no file found for /${pick.name}; suggested by name only`,
        )
      }
      if (file) injected.add(pick.name)
    } else if (injectContent) {
      // Content mode with nothing picked says nothing: "no skill is relevant"
      // would talk the model out of loading one from the listing on its own.
      block = null
    } else {
      block = suggestionBlock(pick, hideListing)
    }
    if (!block) return next(e)
    // Attached on the way down: one block after the prompt as typed, read by
    // the model and never shown to the person.
    return next({ ...e, context: [...(e.context ?? []), block] })
  })

  // An injected skill lives in the conversation, not the process: `/clear`
  // or a resume starts another under the same worker, and a compaction may
  // summarize the block away. Either way the next pick goes in whole again.
  on('session.end', async ($, e, next) => {
    injected.clear()
    suggested = null
    return next(e)
  })
  on('session.compact', async ($, e, next) => {
    if (!e.agentId) injected.clear()
    return next(e)
  })

  // find_skill: the prompt's suggestion is made once, from the prompt alone;
  // a sub-task that turns up mid-turn is the model's to look up. Registered
  // at session.start so the tool list, and the prompt cache, stay put; the
  // full name is the engine's (it depends on how the plugin was loaded).
  let findSkillName = ''
  on('session.start', async ($, e, next) => {
    // Without a backend that reranks, nothing would check the ranking's pick,
    // and the gate is left out: the tool is not offered.
    const vetted = backendOf(await $.env.get('TYPESAFE_API_KEY'), await $.env.get('AI_GATEWAY_API_KEY')).active && rerankEnabled
    if (findSkill && !vetted && logDecisions) {
      $.ui.log('[jev-skill-suggestion] find_skill not offered: it needs a TypeSafe or Gateway key and rerank on')
    }
    if (findSkill && vetted) {
      try {
        findSkillName = (await $.tool.register(FIND_SKILL_TOOL)).tool
      } catch (error) {
        $.ui.log(`[jev-skill-suggestion] could not register find_skill: ${String(error)}`)
      }
    }
    return next(e)
  })
  // Left to the engine, a plugin's tool waits behind ToolSearch, named but
  // without its description: the model would have to guess at it, which is
  // the very thing the tool is for.
  on('tool.describe', async ($, e, next) => {
    const out = await next(e)
    return findSkillName && e.tool === findSkillName ? { ...out, isDeferred: false } : out
  })
  on('tool.call', async ($, e, next) => {
    if (!findSkillName || e.tool !== findSkillName) return next(e)
    const task = 'task' in e && typeof e.task === 'string' ? e.task.trim() : ''
    // The model loads the answer with the Skill tool, so only what the
    // engine lists is offered; before the listing is seen, nothing is.
    let answer: Skill | null | 'unavailable' = 'unavailable'
    try {
      const context = await contextFor($, state, null, e.agentId)
      const choice = task && listed.size > 0 ? await choose($, state, task, { restrictTo: listed, askGate: false, context }) : null
      if (choice?.answered) answer = choice.pick
      if (choice) {
        const { reason, answered, trace } = choice
        await record($, state, { source: 'find_skill', text: task, context, pick: choice.pick?.name ?? null, reason, answered, trace, agentId: e.agentId })
      }
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] find_skill failed: ${String(error)}`)
    }
    if (logDecisions) {
      const outcome = answer === 'unavailable' ? 'lookup unavailable' : answer ? `suggesting /${answer.name}` : 'no suggestion'
      $.ui.log(`[jev-skill-suggestion] find_skill${e.agentId ? ` (${e.agentId})` : ''} "${task}": ${outcome}`)
    }
    // The latest pick, prompt's or find_skill's, is what a skill.prompt that
    // follows is measured against: without it, a skill loaded on
    // find_skill's word would be logged as one nothing suggested.
    if (answer && answer !== 'unavailable') suggested = answer.name
    return { result: findSkillResult(answer) }
  })

  on('skill.prompt', { skill: 'jev-skill-suggestion:setup' }, async ($, e, next) => {
    // The plugin's own setup command: its markdown is a placeholder, and the
    // prompt the model reads is written here, from the roster as the engine
    // has it and the user settings as they are. The model does the editing
    // with its own tools, so the change shows as a diff and asks permission.
    const mode = /\brestore\b/i.test(e.text) ? 'restore' : 'apply'
    // No plan from a partial roster or unreadable settings: the edit would
    // hide too little, and the backup would save the wrong values.
    let commands: Awaited<ReturnType<typeof $.command.list>> = []
    try {
      commands = await listCommands($, state, await configDirFor($))
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] setup: could not list the skills: ${String(error)}`)
      return next({ ...e, text: setupAborted(`the skills could not be listed (${String(error)})`) })
    }
    const configDir = configDirOf((await $.env.get('HOME')) ?? '~', await $.env.get('CLAUDE_CONFIG_DIR'))
    const settingsPath = `${configDir}/settings.json`
    const backupPath = `${configDir}/jev-skill-suggestion.skill-overrides.backup.json`
    let json: string | null = null
    try {
      if (await $.fs.exists(settingsPath)) json = await $.fs.read(settingsPath)
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] setup: could not read ${settingsPath}: ${String(error)}`)
      return next({ ...e, text: setupAborted(`${settingsPath} exists but could not be read (${String(error)})`) })
    }
    const settings = readSkillSettings(json)
    const plan = setupPlan(commands, settings, new Set([SETUP_COMMAND]))
    // An earlier run's backup is reused only if it is one: a file that is
    // not this mod's, or is corrupt, is nothing restore could apply, so no
    // setup is built on top of it.
    let backupExists = false
    try {
      backupExists = await $.fs.exists(backupPath)
      if (backupExists && !validBackup(await $.fs.read(backupPath))) {
        $.ui.log(`[jev-skill-suggestion] setup: ${backupPath} is not a valid backup`)
        return next({
          ...e,
          text: setupAborted(
            `${backupPath} exists but is not a backup this mod wrote (expected {"skillOverrides": {...}, "disableBundledSkills": true|false|null}); ask the user to inspect it and move it away, or fix it, before running the setup again`,
          ),
        })
      }
    } catch (error) {
      $.ui.log(`[jev-skill-suggestion] setup: could not read ${backupPath}: ${String(error)}`)
      return next({ ...e, text: setupAborted(`${backupPath} could not be read (${String(error)})`) })
    }
    if (logDecisions) {
      $.ui.log(
        `[jev-skill-suggestion] setup (${mode}): ${plan.hide.length} to hide, ${plan.alreadyHidden.length} already hidden, ${plan.locked.length} locked by a plugin`,
      )
    }
    return next({ ...e, text: setupInstructions(mode, plan, settings, settingsPath, backupPath, backupExists) })
  })

  on('skill.prompt', async ($, e, next) => {
    // Observation only: whether the model took the suggestion, or reached for
    // a skill it was never told about, is the one measure of this mod's worth.
    if (logDecisions && e.skill !== SETUP_COMMAND) {
      const how =
        suggested === e.skill
          ? 'as suggested'
          : suggested
            ? `suggested was /${suggested}`
            : 'nothing was suggested'
      $.ui.log(`[jev-skill-suggestion] skill /${e.skill} loaded (${how})`)
    }
    if (e.skill !== SETUP_COMMAND) await record($, state, { loaded: e.skill, suggested })
    return next(e)
  })
}

